import numpy as np, math, os
fn='optimized.xyz'
print(os.path.exists(fn), os.path.getsize(fn) if os.path.exists(fn) else None)
with open(fn) as f:
    lines=f.read().strip().splitlines()
print(lines[0], lines[1])
atoms=[]
for line in lines[2:]:
    el,x,y,z=line.split()[:4]
    atoms.append((el,float(x),float(y),float(z)))
print('atoms',len(atoms))
def pos(i): return np.array(atoms[i][1:],float)
def dist(i,j): return np.linalg.norm(pos(i)-pos(j))
def ang(i,j,k):
    v1=pos(i)-pos(j); v2=pos(k)-pos(j)
    return math.degrees(math.acos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
for name,i,j,target in [('Pd-P',7,8,2.30),('Pd-Cu',7,1,2.02),('Pd-Cd',7,5,2.02),('Cu=Cex',1,0,1.34),('Cd=Cex',5,6,1.34),('Cu-C2',1,2,1.50),('Cd-C6',5,4,1.50),('O-C2',3,2,1.43),('O-C6',3,4,1.43),('P-C9',8,9,1.84),('P-C10',8,10,1.84),('P-C11',8,11,1.84)]:
    print(f'{name:8s} {dist(i,j):.3f} target {target:.2f} err {dist(i,j)-target:+.3f}')
print('angles Pd:', round(ang(1,7,5),1), round(ang(1,7,8),1), round(ang(5,7,8),1))
print('angles Cu:', round(ang(7,1,2),1), round(ang(7,1,0),1), round(ang(2,1,0),1))
print('angles Cd:', round(ang(7,5,4),1), round(ang(7,5,6),1), round(ang(4,5,6),1))
# C-H bond length range
for i,a in enumerate(atoms):
    if a[0]=='C':
        hs=[j for j,b in enumerate(atoms) if b[0]=='H' and dist(i,j)<1.3]
        if hs:
            print('C',i,'Hs',hs,'CH', [round(dist(i,j),3) for j in hs])
